# Looking at row 5 interior: [4, 2, 4, 4, 4, 2, 4]
# This is columns 4-10 in row 5
# The 4s are at cols 4, 6, 7, 8, 10
# Let me check distances from corners (3,4), (3,10), (9,4), (9,10)

corners = [(3,4), (3,10), (9,4), (9,10)]
def dist_to_corner(r, c):
    return min(abs(r-pr) + abs(c-pc) for pr, pc in corners)

print("Distance from closest corner for each interior cell:")
for r in range(3, 10):
    row = []
    for c in range(4, 11):
        d = dist_to_corner(r, c)
        row.append(d)
    print(f"Row {r}: {row}")

# The pattern seems to be based on parity of distance
print("\nExpected vs parity:")
for r in range(3, 10):
    row = []
    for c in range(4, 11):
        d = dist_to_corner(r, c)
        if (r,c) == (6,7):
            row.append(3)
        elif d % 2 == 1:
            row.append(4)
        else:
            row.append(2)
    print(f"Row {r} (expected): {row}")

